retail-operations-dashboard

Dieses Beispiel orientiert sich an einem operativen Monitoring-Dashboard und kombiniert 10 Karten: abgefragte Geschäftskennzahlen, Umsatzanteile nach Kategorie und Kundengruppe, Umsatz- und Gewinntrends, Provinzranglisten, Lieferverteilung, Kundendetails und Handlungsempfehlungen. Auf breiten Bildschirmen stehen vier Karten in der ersten Zeile, im Dokumentationsbereich zwei Spalten und auf Mobilgeräten eine Spalte.

Tags: dashboard multi-column responsive operations

export default () => {
  const [dashboardBuilder, setDashboardBuilder] = useState<VBIDashboardBuilder | null>(null)
  const [error, setError] = useState<string | null>(null)
  const locale = useLang() as DashboardRendererProps['locale']

  useEffect(() => {
    let cancelled = false
    const run = async () => {
      try {
        const LocalVBI = createVBI()
        // 所有图表与洞察注册在同一个 VBI 实例中，数据来自 supermarket 演示连接器。
        const createChart = (chartType: string) => {
          const chart = LocalVBI.chart.create(LocalVBI.chart.createEmpty('demoSupermarket'))
          chart.chartType.changeChartType(chartType)
          return chart
        }

        const totals = createChart('table')
        totals.measures.add('sales', node => node.setAlias('销售额').setAggregate({ func: 'sum' }))
        totals.measures.add('profit', node => node.setAlias('利润').setAggregate({ func: 'sum' }))
        totals.measures.add('order_id', node => node.setAlias('订单数').setAggregate({ func: 'countDistinct' }))
        totals.measures.add('customer_id', node => node.setAlias('客户数').setAggregate({ func: 'countDistinct' }))
        totals.measures.add('amount', node => node.setAlias('销售件数').setAggregate({ func: 'sum' }))

        const salesSummary = LocalVBI.insight.create(LocalVBI.insight.createEmpty())
        const customerSummary = LocalVBI.insight.create(LocalVBI.insight.createEmpty())
        const actions = LocalVBI.insight.create(LocalVBI.insight.createEmpty())
        actions.setContent('01  区域经营：结合销售排行与利润表现，优先跟进高贡献区域。\n\n02  客户维护：对高销售客户检查利润质量，制定分层回访计划。\n\n03  履约复盘：按配送方式观察订单分布，结合服务成本调整资源。')

        const categoryShare = createChart('donut')
        categoryShare.dimensions.add('product_type', node => node.setAlias('品类'))
        categoryShare.measures.add('sales', node => node.setAlias('销售额').setAggregate({ func: 'sum' }))

        const customerShare = createChart('donut')
        customerShare.dimensions.add('customer_type', node => node.setAlias('客群'))
        customerShare.measures.add('sales', node => node.setAlias('销售额').setAggregate({ func: 'sum' }))

        const monthlyTrend = createChart('dualAxis')
        monthlyTrend.dimensions.add('order_date', node => node.setAlias('月份').setAggregate({ func: 'toMonth' }).setSort({ order: 'asc' }))
        monthlyTrend.measures.add('sales', node => node.setAlias('销售额').setEncoding('primaryYAxis').setAggregate({ func: 'sum' }))
        monthlyTrend.measures.add('profit', node => node.setAlias('利润').setEncoding('secondaryYAxis').setAggregate({ func: 'sum' }))
        monthlyTrend.limit.setLimit(12)

        const provinceRanking = createChart('bar')
        provinceRanking.dimensions.add('province', node => node.setAlias('省份'))
        provinceRanking.measures.add('sales', node => node.setAlias('销售额').setAggregate({ func: 'sum' }).setSort({ order: 'desc' }))
        provinceRanking.limit.setLimit(6)

        const categoryProfit = createChart('column')
        categoryProfit.dimensions.add('product_type', node => node.setAlias('品类'))
        categoryProfit.measures.add('profit', node => node.setAlias('利润').setAggregate({ func: 'sum' }))

        const deliveryOrders = createChart('column')
        deliveryOrders.dimensions.add('delivery_method', node => node.setAlias('配送方式'))
        deliveryOrders.measures.add('order_id', node => node.setAlias('订单数').setAggregate({ func: 'countDistinct' }))

        const topCustomers = createChart('table')
        topCustomers.dimensions.add('customer_name', node => node.setAlias('客户'))
        topCustomers.measures.add('sales', node => node.setAlias('销售额').setAggregate({ func: 'sum' }).setSort({ order: 'desc' }).setFormat({ autoFormat: true }))
        topCustomers.measures.add('profit', node => node.setAlias('利润').setAggregate({ func: 'sum' }).setFormat({ autoFormat: true }))
        topCustomers.limit.setLimit(6)

        const dashboardBuilder = LocalVBI.dashboard.create({
          ...LocalVBI.dashboard.createEmpty(),
          // 断点基于仪表盘内容宽度；400px 起让文档预览也能并排展示卡片。
          breakpoints: { xxl: 1600, xl: 1200, lg: 960, md: 640, sm: 400, xs: 0 },
          meta: {
            title: '零售运营全景',
            description: 'RETAIL OPERATIONS / 演示数据全量汇总 · 趋势展示最早 12 个月',
          },
        })

        // 摘要也来自真实查询，通过 Insight Builder 保存显示文本。
        const summary = await totals.buildVSeed()
        const readTotal = (field: string) => {
          const id = totals.measures.find(node => node.getField() === field)?.getId()
          return id ? Number(summary.dataset[0]?.[id] ?? 0) : 0
        }
        const sales = readTotal('sales')
        const profit = readTotal('profit')
        salesSummary.setContent([
          `销售额  ¥${(sales / 10000).toFixed(2)} 万`,
          `利润  ¥${(profit / 10000).toFixed(2)} 万`,
          `利润率  ${sales ? (profit / sales * 100).toFixed(1) : '0.0'}%`,
        ].join('\n\n'))
        customerSummary.setContent([
          `订单  ${readTotal('order_id').toFixed(0)} 单`,
          `客户  ${readTotal('customer_id').toFixed(0)} 位`,
          `销量  ${readTotal('amount').toFixed(0)} 件`,
        ].join('\n\n'))

        dashboardBuilder.insight.add(widget => {
          widget.setInsightId(salesSummary)
            .setTitle('经营快照')
            .setDescription('全量销售与利润')
            .setLayouts({
              lg: { x: 0, y: 0, w: 3, h: 4 },
              md: { x: 0, y: 0, w: 3, h: 3 },
              sm: { x: 0, y: 0, w: 2, h: 3 },
              xs: { x: 0, y: 0, w: 2, h: 3 },
            })
        })

        dashboardBuilder.insight.add(widget => {
          widget.setInsightId(customerSummary)
            .setTitle('客户与订单')
            .setDescription('去重客户与订单统计')
            .setLayouts({
              lg: { x: 3, y: 0, w: 3, h: 4 },
              md: { x: 3, y: 0, w: 3, h: 3 },
              sm: { x: 2, y: 0, w: 2, h: 3 },
              xs: { x: 0, y: 3, w: 2, h: 3 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(categoryShare)
            .setTitle('品类销售占比')
            .setLayouts({
              lg: { x: 6, y: 0, w: 3, h: 4 },
              md: { x: 0, y: 3, w: 3, h: 4 },
              sm: { x: 0, y: 3, w: 4, h: 4 },
              xs: { x: 0, y: 6, w: 2, h: 4 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(customerShare)
            .setTitle('客群销售占比')
            .setLayouts({
              lg: { x: 9, y: 0, w: 3, h: 4 },
              md: { x: 3, y: 3, w: 3, h: 4 },
              sm: { x: 0, y: 7, w: 4, h: 4 },
              xs: { x: 0, y: 10, w: 2, h: 4 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(monthlyTrend)
            .setTitle('销售与利润趋势')
            .setDescription('月度双轴对比 · 最早 12 个月')
            .setLayouts({
              lg: { x: 0, y: 4, w: 8, h: 5 },
              md: { x: 0, y: 7, w: 6, h: 5 },
              sm: { x: 0, y: 11, w: 4, h: 5 },
              xs: { x: 0, y: 14, w: 2, h: 5 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(provinceRanking)
            .setTitle('省份销售 TOP 6')
            .setDescription('按销售额降序排列')
            .setLayouts({
              lg: { x: 8, y: 4, w: 4, h: 5 },
              md: { x: 0, y: 12, w: 3, h: 5 },
              sm: { x: 0, y: 16, w: 4, h: 5 },
              xs: { x: 0, y: 19, w: 2, h: 5 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(categoryProfit)
            .setTitle('品类利润')
            .setLayouts({
              lg: { x: 0, y: 9, w: 4, h: 5 },
              md: { x: 3, y: 12, w: 3, h: 5 },
              sm: { x: 0, y: 21, w: 4, h: 5 },
              xs: { x: 0, y: 24, w: 2, h: 5 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(deliveryOrders)
            .setTitle('配送订单分布')
            .setLayouts({
              lg: { x: 4, y: 9, w: 4, h: 5 },
              md: { x: 0, y: 17, w: 3, h: 5 },
              sm: { x: 0, y: 26, w: 4, h: 5 },
              xs: { x: 0, y: 29, w: 2, h: 5 },
            })
        })

        dashboardBuilder.chart.add(widget => {
          widget.setChart(topCustomers)
            .setTitle('重点客户 TOP 6')
            .setDescription('销售额与利润明细')
            .setLayouts({
              lg: { x: 8, y: 9, w: 4, h: 5 },
              md: { x: 3, y: 17, w: 3, h: 5 },
              sm: { x: 0, y: 31, w: 4, h: 5 },
              xs: { x: 0, y: 34, w: 2, h: 5 },
            })
        })

        dashboardBuilder.insight.add(widget => {
          widget.setInsightId(actions)
            .setTitle('经营观察与行动')
            .setDescription('结合趋势、结构与明细制定下一步计划')
            .setLayouts({
              lg: { x: 0, y: 14, w: 12, h: 3 },
              md: { x: 0, y: 22, w: 6, h: 4 },
              sm: { x: 0, y: 36, w: 4, h: 4 },
              xs: { x: 0, y: 39, w: 2, h: 4 },
            })
        })
        if (!cancelled) setDashboardBuilder(dashboardBuilder)
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : String(err))
      }
    }
    void run()
    return () => { cancelled = true }
  }, [])

  if (error) return <div role='alert'>{error}</div>
  if (!dashboardBuilder) return <div role='status'>Loading...</div>

  return <DashboardRenderer builder={dashboardBuilder} mode='edit' locale={locale} />
