export default () => {
  const [dashboardBuilder, setDashboardBuilder] = useState<VBIDashboardBuilder | null>(null)
  const [error, setError] = useState<string | null>(null)
  const locale = useLang() as DashboardRendererProps['locale']

  useEffect(() => {
    let cancelled = false
    const run = async () => {
      try {
        const LocalVBI = createVBI()
        const categorySalesChart = LocalVBI.chart.create(LocalVBI.chart.createEmpty('demoSupermarket'))
        categorySalesChart.chartType.changeChartType('bar')
        categorySalesChart.dimensions.add('product_type', dimension => dimension.setAlias('商品品类'))
        categorySalesChart.measures.add('sales', measure => measure.setAlias('销售额').setEncoding('xAxis').setAggregate({ func: 'sum' }))
        categorySalesChart.limit.setLimit(8)

        const discountProfitChart = LocalVBI.chart.create(LocalVBI.chart.createEmpty('demoSupermarket'))
        discountProfitChart.chartType.changeChartType('scatter')
        discountProfitChart.dimensions.add('discount', dimension => dimension.setAlias('折扣'))
        discountProfitChart.measures.add('profit', measure => measure.setAlias('利润').setEncoding('yAxis').setAggregate({ func: 'sum' }))

        const promotionInsight = LocalVBI.insight.create(LocalVBI.insight.createEmpty())
        promotionInsight.setContent("高折扣品类带来的销售增长未完全转化为利润，需要收紧促销门槛。")

        const resources = {
          charts: { categorySalesChart, discountProfitChart },
          insights: { promotionInsight },
        }

        const dashboardBuilder = LocalVBI.dashboard.create({
          ...LocalVBI.dashboard.createEmpty(),
          meta: { title: '商品运营看板' },
        })

        if (!dashboardBuilder.isEmpty()) throw new Error('dashboard should be empty')

        dashboardBuilder.chart.add(chart => {
          chart
            .setChart(resources.charts.categorySalesChart)
            .setTitle('品类销售')
            .setDescription('初版品类销售布局')
            .setLayouts({ lg: { x: 0, y: 0, w: 6, h: 4 }, md: { x: 0, y: 0, w: 6, h: 4 } })
        })
        dashboardBuilder.chart.add(chart => {
          chart
            .setChart(resources.charts.discountProfitChart)
            .setTitle('折扣利润散点')
            .setLayouts({ lg: { x: 6, y: 0, w: 6, h: 4 }, md: { x: 0, y: 4, w: 6, h: 4 } })
        })
        dashboardBuilder.insight.add(insight => {
          insight
            .setInsightId(resources.insights.promotionInsight)
            .setTitle('促销洞察')
            .setLayouts({ lg: { x: 0, y: 4, w: 12, h: 3 }, md: { x: 0, y: 8, w: 6, h: 3 } })
        })

        const [categoryWidget, discountWidget] = dashboardBuilder.chart.toJSON()
        const [promotionWidget] = dashboardBuilder.insight.toJSON()
        if (dashboardBuilder.chart.find(resources.charts.categorySalesChart.getUUID())?.getId() !== categoryWidget.id) throw new Error('chart reference should resolve')
        if (dashboardBuilder.insight.find(resources.insights.promotionInsight.getUUID())?.getId() !== promotionWidget.id) throw new Error('insight reference should resolve')

        dashboardBuilder.chart.update(categoryWidget.id, chart => {
          chart
            .setTitle('重点品类销售')
            .setDescription('更新后保留 md 布局，并合并新的 lg 布局')
            .setLayouts({ lg: { x: 0, y: 0, w: 7, h: 5 } })
        })
        dashboardBuilder.insight.update(promotionWidget.id, insight => {
          insight
            .setDescription('更新后的促销策略说明')
            .setLayouts({ lg: { x: 7, y: 0, w: 5, h: 5 } })
        })
        dashboardBuilder.chart.remove(discountWidget.id)
        if (dashboardBuilder.chart.get(discountWidget.id)) throw new Error('removed chart should be absent')

        for (const widget of dashboardBuilder.chart.toJSON()) {
          dashboardBuilder.chart.remove(widget.id)
        }
        for (const widget of dashboardBuilder.insight.toJSON()) {
          dashboardBuilder.insight.remove(widget.id)
        }
        if (!dashboardBuilder.isEmpty()) throw new Error('dashboard should be empty')

        dashboardBuilder.chart.add(chart => {
          chart
            .setChart(resources.charts.categorySalesChart)
            .setTitle('最终品类销售')
            .setDescription('清空草稿后重建的主图')
            .setLayouts({ lg: { x: 0, y: 0, w: 7, h: 5 }, md: { x: 0, y: 0, w: 6, h: 4 } })
        })
        dashboardBuilder.insight.add(insight => {
          insight
            .setInsightId(resources.insights.promotionInsight)
            .setTitle('最终促销洞察')
            .setDescription('清空草稿后重建的洞察')
            .setLayouts({ lg: { x: 7, y: 0, w: 5, h: 5 }, md: { x: 0, y: 4, w: 6, h: 3 } })
        })
        if (dashboardBuilder.isEmpty()) throw new Error('dashboard should contain widgets')
        if (!cancelled) setDashboardBuilder(dashboardBuilder)
      } catch (err) {
