VSeed unterstützt viele Chart-Typen. Über die Eigenschaft chartType kannst du einfach zwischen unterschiedlichen Visualisierungsformen wechseln, darunter Standardcharts, Pivot-Tabellen und mehr.

registerAll()

const Demo = () => {
  const ref = useRef<HTMLDivElement>(null)
  const [chartType, setChartType] = useState('line')
  const chartTypes = [
    'table',
    'pivotTable',
    // cartesian
    'line',
    'column',
    'columnPercent',
    'columnParallel',
    'bar',
    'barPercent',
    'barParallel',
    'area',
    'areaPercent',
    // polar
    'pie',
    'donut',
    'radar',
    'roseParallel',
    'rose',
    'scatter',
    'dualAxis',
    // other
    'funnel',
    'heatmap',
  ]

  const changeChartType = (c) => () => {
    setChartType(c)
  }

  useEffect(() => {
    if (!ref.current) {
      return
    }

    const vseed: VSeed = {
      chartType,
      dataset: [
        { date: '2019', profit: 10, sales: 100 },
        { date: '2020', profit: 30, sales: 200 },
        { date: '2021', profit: 30, sales: 300 },
        { date: '2022', profit: 50, sales: 400 },
        { date: '2023', profit: 40, sales: 500 },
      ],
    }
    const builder = Builder.from(vseed)
    const spec = builder.build()

    if (isTable(vseed)) {
      const tableInstance = new ListTable(ref.current, spec)
      return () => tableInstance.release()
    } else if (isPivotTable(vseed)) {
      const tableInstance = new PivotTable(ref.current, spec)
      return () => tableInstance.release()
    } else {
      const vchart = new VChart(spec, { dom: ref.current })
      vchart.renderSync()
      return () => vchart.release()
    }
  }, [chartType])

  return (
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      <div>
        {chartTypes.map((d) => {
          return (
            <span key={d} style={{ margin: '0 2px 0 0' }}>
              <button
                onClick={changeChartType(d)}
                style={{ fontSize: 10, padding: '0 2px', border: '1px solid #cccccc' }}
              >
                {d}
              </button>
            </span>
          )
        })}
      </div>
      <div ref={ref} style={{ height: 260, width: '100%' }}></div>
    </div>
  )
}

